mapper.select:
SELECT a.agent_no AS agentNo, a.agent_name AS agentName, a.agent_short_name AS agentShortName, a.contact_name AS contactName, a.contact_tel AS contactTel, a.contact_email AS contactEmail, a.parent_agent_no AS parentAgentNo, p.agent_name AS parentAgentName, a.agent_level AS agentLevel, a.profit_rate AS profitRate, a.settlement_cycle AS settlementCycle, a.min_settlement_amount AS minSettlementAmount, a.state AS state, a.remark AS remark, a.created_at AS createdAt, a.updated_at AS updatedAt FROM t_agent_info a LEFT JOIN t_agent_info p ON p.agent_no = a.parent_agent_no
AND a.agent_name LIKE CONCAT('%', #{agentName}, '%')
AND a.agent_level = #{agentLevel}
AND a.state = #{state}
AND a.parent_agent_no = #{parentAgentNo}
ORDER BY a.created_at DESC
